const rows = $input.all().map(item => item.json);
const state = $getWorkflowStaticData('global');
const currentDay = Number(state.serie50DiaAtual || 1);

if (currentDay > 50) {
  throw new Error('A serie 50 dias de musica ja terminou. Reinicie o contador manualmente no workflow static data.');
}

const text = (value) => String(value ?? '').trim();
const isYes = (value) => ['sim', 'yes', 'true', '1'].includes(text(value).toLowerCase());
const asNumber = (value, fallback = 9999) => {
  const num = Number(value);
  return Number.isFinite(num) ? num : fallback;
};

const candidates = rows
  .filter((row) => isYes(row.serie_50_dias))
  .filter((row) => text(row.status_publicacao).toLowerCase() === 'pronto')
  .sort((a, b) => asNumber(a.ordem_50_dias) - asNumber(b.ordem_50_dias));

if (!candidates.length) {
  throw new Error('Nenhum item elegivel encontrado para a serie 50 dias de musica.');
}

const selected = candidates.find((row) => asNumber(row.ordem_50_dias, 0) === currentDay);
if (!selected) {
  throw new Error(`Nao encontrei item elegivel para o dia ${currentDay}. Verifique as colunas serie_50_dias, ordem_50_dias e status_publicacao.`);
}

const musica = text(selected.musica) || 'Musica a confirmar';
const compositor = text(selected.compositor) || 'a confirmar';
const interprete = text(selected.interprete) || 'a confirmar';
const genero = text(selected.genero_musical);
const origemAutoral = text(selected.origem_autoral).toLowerCase();
const header = compositor && compositor !== 'a confirmar'
  ? `#${currentDay} ${musica} (${compositor})`
  : `#${currentDay} ${musica}`;

const songLine = genero
  ? `${musica} aparece hoje em clima de ${genero}, em um recorte curto para seguir a serie.`
  : `${musica} aparece hoje em um recorte curto para seguir a serie.`;

let artistLine = '';
if (origemAutoral === 'autor_proprio' && compositor !== 'a confirmar') {
  artistLine = `${compositor} assina esta composicao, em mais um ponto do repertorio autoral do projeto.`;
} else if (compositor !== 'a confirmar' && interprete !== 'a confirmar' && compositor !== interprete) {
  artistLine = `${compositor} assina a canção, aqui lembrada na leitura ligada a ${interprete}.`;
} else if (interprete !== 'a confirmar') {
  artistLine = `${interprete} ajuda a manter essa musica viva na memoria de quem escuta.`;
} else if (compositor !== 'a confirmar') {
  artistLine = `${compositor} e o nome por tras da composicao de hoje.`;
} else {
  artistLine = 'Uma musica que segue encontrando escuta em diferentes leituras.';
}

const ctaAudio = 'Ouça Samba da Gabriela nas plataformas de streaming e no YouTube.';
const ctas = {
  tiktok: 'Siga para acompanhar os proximos dias da serie.',
  instagram: 'Siga para acompanhar os proximos dias da serie.',
  facebook: 'Acompanhe a pagina para seguir os proximos dias da serie.',
  youtube: 'Inscreva-se no canal para acompanhar os proximos dias da serie.'
};

const buildCaption = (platform) => [header, songLine, artistLine, ctaAudio, ctas[platform]].join('\n');

return [{
  json: {
    ...selected,
    numero_do_dia: currentDay,
    drive_file_id: text(selected.drive_file_id || selected.video_id),
    header,
    song_line: songLine,
    artist_line: artistLine,
    caption_tiktok: buildCaption('tiktok'),
    caption_instagram: buildCaption('instagram'),
    caption_facebook: buildCaption('facebook'),
    caption_youtube: buildCaption('youtube')
  }
}];

const original = $('Select Day Item And Build Captions').first().json;
const response = $input.first().json || {};
return [{
  json: {
    ...original,
    tiktok_status: response.statusCode && response.statusCode >= 200 && response.statusCode < 300 ? 'postado' : 'erro_tiktok',
    tiktok_response: response
  },
  binary: $input.first().binary
}];

const previous = $('Capture TikTok Status').first().json;
const response = $input.first().json || {};
return [{
  json: {
    ...previous,
    instagram_status: response.statusCode && response.statusCode >= 200 && response.statusCode < 300 ? 'postado' : 'erro_instagram',
    instagram_response: response
  },
  binary: $input.first().binary
}];

const previous = $('Capture Instagram Status').first().json;
const response = $input.first().json || {};
return [{
  json: {
    ...previous,
    facebook_status: response.statusCode && response.statusCode >= 200 && response.statusCode < 300 ? 'postado' : 'erro_facebook',
    facebook_response: response
  },
  binary: $input.first().binary
}];

const previous = $('Capture Facebook Status').first().json;
const response = $input.first().json || {};
const youtube_status = response.statusCode && response.statusCode >= 200 && response.statusCode < 300 ? 'postado' : 'erro_youtube';
const statuses = [previous.tiktok_status, previous.instagram_status, previous.facebook_status, youtube_status];
const allOk = statuses.every((status) => status === 'postado');
const anyOk = statuses.some((status) => status === 'postado');
const state = $getWorkflowStaticData('global');
const currentDay = Number(state.serie50DiaAtual || 1);

if (allOk) {
  state.serie50DiaAtual = currentDay + 1;
  state.serie50UltimoPublicado = previous.drive_file_id || '';
  state.serie50UltimaExecucao = new Date().toISOString();
}

return [{
  json: {
    ...previous,
    youtube_status,
    youtube_response: response,
    publish_success: allOk,
    final_status: allOk ? 'postado' : (anyOk ? 'pendente_canal' : 'erro'),
    numero_publicado_50_dias: allOk ? currentDay : null,
    data_publicacao_50_dias: allOk ? new Date().toISOString() : null,
    proximo_dia: allOk ? currentDay + 1 : currentDay
  }
}];
